class Bus {
  private widgets: Widget[] = [];
  register(w: Widget) { this.widgets.push(w); }
  broadcast(sender: Widget, msg: string) { this.widgets.forEach(w => w.receive(sender, msg)); }
}

class Widget {
  constructor(private bus: Bus) {}
  click() { this.bus.broadcast(this, 'click'); }
